      "trigger": "Response includes 0 in the move set (e.g., extending powers of 2 to '2^k for k >= -infinity' or listing 0). Including 0 trivializes the game."
    },
    "wrong_move_set_missing_one": {
      "trigger": "Response drops 1 from the move set (e.g., starts at 2^1 = 2, or claims '1 is trivial and shouldn't count'). Trigger phrases: 'M = {2, 4, 8, ...}', 'we ignore the trivial move 1'."
    },
    "extended_move_set_with_extras": {
      "trigger": "Response enlarges move set with non-power-of-two values (3, 5, 6, 7). Examples: 'M = {1, 2, 3, 4, 5, 6, 7, 8, ...}' (all integers), 'M = {1, 3, 7, 15, 31, 63}' (Mersenne-style), 'M = {1, 2, 4, 6, 8, ...}' (even numbers)."
    },
    "confused_pn_convention": {
      "trigger": "Response swaps P/N labels globally WITHOUT explicitly invoking misère. Trigger phrases: 'position 0 is N because player to move wins by having no moves', 'P-position means win for player to move'."
    },
    "base_case_set_to_n": {
      "trigger": "Response sets base case n=0 to N rather than P, but does NOT invert entire convention. Distinct from confused_pn_convention because only base case is wrong, recurrence otherwise unchanged."
    },
    "treats_game_as_misere": {
      "trigger": "Response explicitly invokes misère convention (last move loses). Trigger phrases: 'we apply the misère convention', 'the player who takes the last stone loses'."
    },
    "computes_grundy_instead_of_pn": {
      "trigger": "Response computes Sprague-Grundy values via mex of reachable Grundy values rather than binary P/N DP. Trigger phrases: 'G(n) = mex{G(n-1), G(n-2), G(n-4), ...}', 'the Grundy number at n is ...'."
    },
    "confuses_with_nim_xor": {
      "trigger": "Response invokes Nim XOR rule directly (treating single pile as multiple piles). Trigger phrases: 'by Nim XOR the position is P iff XOR = 0', 'applying the Nim Sprague-Grundy XOR rule'."
    },
    "arithmetic_recursion_error": {
      "trigger": "Response applies DP transition incorrectly at specific positions despite having correct stated framework. Requires that stated DP rule is correct but specific positions are mislabeled due to arithmetic slip."
    },
    "claims_wrong_period": {
      "trigger": "Response asserts P-position period other than 3 (actual period). Common false claims: period 2 (alternating), period 4, period 5, period 8. Trigger phrases: 'the pattern is period 2', 'every other position is P', 'every fourth position is P'."
    },
    "arbitrary_pattern_heuristic": {
      "trigger": "Response asserts pattern, rule of thumb, or closed-form formula for P-positions without proof or DP verification. May co-occur with claims_wrong_period."
    },
    "truncated_or_short_string": {
      "trigger": "Response's output P/N string is shorter than 101 characters but still produces a committed string."
    },
    "non_terminating_or_no_final_answer": {
      "trigger": "Response does not produce an identifiable final P/N classification at all. Mutually incompatible with any other code; when it fires, it stands alone."
    }
  },

  "disambiguation_rules": {
    "move_set_codes_mutually_exclusive": "The three move-set codes (wrong_move_set_including_zero, wrong_move_set_missing_one, extended_move_set_with_extras) are mutually exclusive when one captures the primary move-set defect.",
    "confused_pn_vs_base_case": "confused_pn_convention (global swap without misère) and base_case_set_to_n (only base case wrong) distinguished by scope.",
    "treats_game_as_misere_explicit_only": "treats_game_as_misere fires only when response explicitly invokes misère play. Implicit label swap without naming misère is confused_pn_convention.",
    "computes_grundy_vs_nim_xor": "computes_grundy_instead_of_pn (mex over reachable Grundy values) and confuses_with_nim_xor (Nim XOR rule directly) are distinct framework misapplications. Pick the one whose specific framework error fires.",
    "arithmetic_recursion_error_scope": "arithmetic_recursion_error fires when stated recurrence is correct but specific positions mislabeled. It almost always co-occurs with upstream error and is rarely the primary.",
    "claims_wrong_period_vs_heuristic": "claims_wrong_period and arbitrary_pattern_heuristic may co-occur. claims_wrong_period fires when specific period asserted; arbitrary_pattern_heuristic fires when ANY unsupported heuristic appears.",
    "truncated_vs_non_terminating": "truncated_or_short_string fires when output shorter than 101 chars but produces committed string. Distinct from non_terminating_or_no_final_answer which fires only when no committed classification exists.",
    "non_terminating_standalone": "non_terminating_or_no_final_answer stands alone when it fires."
  },

  "primary_failure_code_selection_rules": [
    {
      "condition": "failure_reasons is empty",
      "action": "primary_failure_code MUST be literal string 'NONE'"
    },
    {
      "condition": "non_terminating_or_no_final_answer is present",
      "action": "It stands alone and is the primary"
    },
    {
      "condition": "treats_game_as_misere is present",
      "action": "Prefer it over confused_pn_convention"
    },
    {
      "condition": "One of wrong_move_set_including_zero, wrong_move_set_missing_one, extended_move_set_with_extras is present",
      "action": "That move-set error is upstream of arithmetic_recursion_error, claims_wrong_period, and arbitrary_pattern_heuristic; prefer the move-set code"
    },
    {
      "condition": "confused_pn_convention is present and no move-set code applies",
      "action": "Prefer it over base_case_set_to_n"
    },
    {
      "condition": "base_case_set_to_n is present and no convention swap or move-set error is present",
      "action": "Prefer it over arithmetic_recursion_error"
    },
    {
      "condition": "computes_grundy_instead_of_pn or confuses_with_nim_xor is present and no move-set/convention/base-case error is present",
      "action": "Prefer the framework code over arithmetic_recursion_error and claims_wrong_period"
    },
    {
      "condition": "claims_wrong_period is present and no upstream code applies",
      "action": "Prefer it over arbitrary_pattern_heuristic"
    },
    {
      "condition": "Default",
      "action": "Do NOT pick arithmetic_recursion_error, truncated_or_short_string, or arbitrary_pattern_heuristic as primary when any upstream code applies"
    }
  ],

  "set_match_rule": {
    "failure_reasons_scoring": "The failure_reasons set per response is scored all-or-nothing (set match). Both extra failure-reason codes and missing failure-reason codes are wrong.",
    "typical_count": "Most responses have 2-4 applicable codes. One response has only 1 code (the non-terminating case).",
    "application_rule": "Apply a code only when its triggering condition is concretely instantiated in the response's text.",
    "empty_list_rule": "Use empty list [] for failure_reasons exactly when the response's final classification string equals the gold AND no failure-reason trigger fires.",
    "none_primary_rule": "When failure_reasons is empty list, set primary_failure_code to literal string 'NONE'"
  },

  "code_priority_hierarchy": [
    "non_terminating_or_no_final_answer (standalone)",
    "wrong_move_set_including_zero / wrong_move_set_missing_one / extended_move_set_with_extras",
    "treats_game_as_misere",
    "confused_pn_convention",
    "base_case_set_to_n",
    "computes_grundy_instead_of_pn / confuses_with_nim_xor",
    "claims_wrong_period",
    "arbitrary_pattern_heuristic",
    "arithmetic_recursion_error",
    "truncated_or_short_string"
  ],

  "common_anti_patterns": [
    "Asserting period 2 (alternating): Triggers claims_wrong_period, arbitrary_pattern_heuristic, arithmetic_recursion_error",
    "Including 0 in move set: Triggers wrong_move_set_including_zero",
    "Dropping 1 from move set: Triggers wrong_move_set_missing_one",
    "Including extras like 3, 5, 6 or using Mersenne-style values: Triggers extended_move_set_with_extras",
    "Globally swapping labels without naming misère: Triggers confused_pn_convention",
    "Explicitly invoking misère: Triggers treats_game_as_misere",
    "Setting position 0 = N as base-case-only error: Triggers base_case_set_to_n",
    "Computing Grundy via mex: Triggers computes_grundy_instead_of_pn",
    "Applying Nim XOR: Triggers confuses_with_nim_xor",
    "Output shorter than 101 characters: Triggers truncated_or_short_string",
    "Looping without committing: Triggers non_terminating_or_no_final_answer alone"
  ],

  "worked_example": {
    "scenario": "Response derives move set correctly as M = {1, 2, 4, 8, 16, 32, 64}, sets position 0 as P correctly, but asserts 'the P-positions follow period 2 (alternating)' and writes 101-character string labeling even positions as P and odd as N",
    "applicable_codes": ["claims_wrong_period", "arbitrary_pattern_heuristic", "arithmetic_recursion_error"],
    "primary_selection": "claims_wrong_period (per selection rules - period claim takes priority over heuristic when no upstream error)"
  }
}
